import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Login from './pages/Login';
import Dashboard from './pages/Dashboard';
import Analytics from './pages/Analytics';
import './App.css';

function App() {
  const [token, setToken] = useState(localStorage.getItem('token'));
  const [currentPage, setCurrentPage] = useState('dashboard');

  useEffect(() => {
    if (token) {
      localStorage.setItem('token', token);
    } else {
      localStorage.removeItem('token');
    }
  }, [token]);

  if (!token) {
    return <Login setToken={setToken} />;
  }

  return (
    <div className="App">
      <nav className="main-nav">
        <div className="nav-container">
          <div className="nav-brand">
            <div className="logo">FG</div>
            <h2>FinanceGuard Pro</h2>
          </div>
          <div className="nav-links">
            <button 
              className={`nav-btn ${currentPage === 'dashboard' ? 'active' : ''}`}
              onClick={() => setCurrentPage('dashboard')}
            >
              Dashboard
            </button>
            <button 
              className={`nav-btn ${currentPage === 'analytics' ? 'active' : ''}`}
              onClick={() => setCurrentPage('analytics')}
            >
              Analytics
            </button>
            <button 
              className="nav-btn logout-nav"
              onClick={() => setToken(null)}
            >
              Logout
            </button>
          </div>
        </div>
      </nav>

      <main className="main-content">
        {currentPage === 'dashboard' && <Dashboard token={token} setToken={setToken} />}
        {currentPage === 'analytics' && <Analytics token={token} />}
      </main>
    </div>
  );
}

export default App;
